+static async Task<string> SearchWeb(
+    [Description("The search query string")] string query)
+{
+    Console.WriteLine($"  🌐 Searching: \"{query}\"");
+
+    using var http = new HttpClient();
+    http.DefaultRequestHeaders.UserAgent.ParseAdd(
+        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
+
+    try
+    {
+        // Use DuckDuckGo's HTML search (no API key needed)
+        var encoded = Uri.EscapeDataString(query);
+        var url = $"https://html.duckduckgo.com/html/?q={encoded}";
+        var html = await http.GetStringAsync(url);
+
+        var results = ParseDuckDuckGoResults(html);
+
+        if (results.Count == 0)
+            return $"No results found for \"{query}\".";
+
+        var sb = new StringBuilder();
+        sb.AppendLine($"Search results for \"{query}\":\n");
+        foreach (var r in results.Take(5))
+        {
+            sb.AppendLine($"Title: {r.Title}");
+            sb.AppendLine($"URL:   {r.Url}");
+            sb.AppendLine($"Snippet: {r.Snippet}");
+            sb.AppendLine();
+        }
+        return sb.ToString();
+    }
+    catch (Exception ex)
+    {
+        return $"Search failed: {ex.Message}";
+    }
+}
+
+static List<SearchResult> ParseDuckDuckGoResults(string html)
+{
+    var results = new List<SearchResult>();
+
+    // Parse result blocks between <a class="result__a" ...> tags
+    var linkMarker = "class=\"result__a\"";
+    var snippetMarker = "class=\"result__snippet";
+    var idx = 0;
+
+    while (idx < html.Length && results.Count < 8)
+    {
+        var linkPos = html.IndexOf(linkMarker, idx, StringComparison.Ordinal);
+        if (linkPos < 0) break;
+
+        // Extract href
+        var hrefStart = html.LastIndexOf("href=\"", linkPos, Math.Min(linkPos, 200), StringComparison.Ordinal);
+        var resultUrl = "";
+        if (hrefStart >= 0)
+        {
+            hrefStart += 6;
+            var hrefEnd = html.IndexOf('"', hrefStart);
+            if (hrefEnd > hrefStart)
+                resultUrl = html[hrefStart..hrefEnd];
+        }
+
+        // Extract title (text between > and </a>)
+        var titleStart = html.IndexOf('>', linkPos) + 1;
+        var titleEnd = html.IndexOf("</a>", titleStart, StringComparison.Ordinal);
+        var title = titleEnd > titleStart ? StripHtml(html[titleStart..titleEnd]).Trim() : "";
+
+        // Extract snippet
+        var snippet = "";
+        var snippetPos = html.IndexOf(snippetMarker, titleEnd > 0 ? titleEnd : linkPos + 1, StringComparison.Ordinal);
+        if (snippetPos >= 0)
+        {
+            var snipStart = html.IndexOf('>', snippetPos) + 1;
+            var snipEnd = html.IndexOf("</", snipStart, StringComparison.Ordinal);
+            if (snipEnd > snipStart)
+                snippet = StripHtml(html[snipStart..snipEnd]).Trim();
+        }
+
+        if (!string.IsNullOrWhiteSpace(title))
+            results.Add(new SearchResult(title, resultUrl, snippet));
+
+        idx = (titleEnd > 0 ? titleEnd : linkPos) + 1;
+    }
+
+    return results;
+}
+
+static string StripHtml(string s)
+{
+    var sb = new StringBuilder(s.Length);
+    var inTag = false;
+    foreach (var c in s)
+    {
+        if (c == '<') { inTag = true; continue; }
+        if (c == '>') { inTag = false; continue; }
+        if (!inTag) sb.Append(c);
+    }
+    return System.Net.WebUtility.HtmlDecode(sb.ToString());
+}
+
+static string PromptForTopic()
+{
+    Console.Write("Enter a research topic: ");
+    var topic = Console.ReadLine()?.Trim();
+    if (string.IsNullOrWhiteSpace(topic))
+    {
+        Console.WriteLine("No topic provided. Using default.");
+        topic = "Recent advances in renewable energy technology";
+    }
+    return topic;
+}
+
+// ---------------------------------------------------------------------------
+// Supporting types
+// ---------------------------------------------------------------------------
+
+record SearchResult(string Title, string Url, string Snippet);
+
+/// <summary>Thread-safe notebook for collecting research notes.</summary>
+class Notebook
+{
+    private readonly List<string> _notes = [];
+    private readonly Lock _lock = new();
+
+    [Description("Save a research note. Use this to record an important fact, insight, or finding.")]
+    public string SaveNote(
+        [Description("The note text to save")] string note)
+    {
+        lock (_lock)
+        {
+            _notes.Add(note);
+            Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
+            return $"Note #{_notes.Count} saved successfully.";
+        }
+    }
+
+    [Description("Read all research notes collected so far.")]
+    public string ReadNotes()
+    {
+        lock (_lock)
+        {
+            if (_notes.Count == 0)
+                return "No notes have been saved yet.";
+
+            var sb = new StringBuilder();
+            sb.AppendLine($"Research notes ({_notes.Count} total):\n");
+            for (var i = 0; i < _notes.Count; i++)
+                sb.AppendLine($"[{i + 1}] {_notes[i]}");
+            return sb.ToString();
+        }
+    }
+
+    public List<string> GetAllNotes()
+    {
+        lock (_lock) return [.. _notes];
+    }
+}

